mapper.select:
SELECT log_id, image_url FROM log_images WHERE log_id IN
#{id}
ORDER BY log_id, sort_order, id

SELECT ltr.log_id, t.name FROM log_tag_relations ltr JOIN tags t ON t.id = ltr.tag_id WHERE ltr.log_id IN
#{id}
ORDER BY ltr.log_id, t.id

mapper.update:
UPDATE travel_logs
SET status = 0
WHERE id = #{id}
  AND user_id = #{userId}
  AND status = 1

UPDATE pois
SET rating = (
  SELECT ROUND(AVG(l.rating), 1)
  FROM travel_logs l
  WHERE l.poi_id = #{poiId}
    AND l.status = 1
    AND l.rating IS NOT NULL
)
WHERE id = #{poiId}
  AND EXISTS (
    SELECT 1
    FROM travel_logs l
    WHERE l.poi_id = #{poiId}
      AND l.status = 1
      AND l.rating IS NOT NULL
  )

